def observe(sessions: InteractiveSessions, node: str, attached: dict | None) -> dict:
    """The session's verified live row; SessionGap while a restarting service cannot confirm it yet.

    Only a background id verified live and attached before (`attached`, its row then) earns that wait,
    whatever became of its PID, since an update respawns the session under a new one. How the listing
    itself fails (a missing CLI, a timeout, a non-zero exit, output it cannot parse) is Claude Code's
    business and every such failure is a gap; what the listing says is judged by verified_row.
    """
    try:
        rows = sessions.inventory()
    except Exception as error:
        if attached is None:
            raise
        raise SessionGap(str(error)) from error
    return verified_row(sessions, node, rows, attached)


def verified_row(sessions: InteractiveSessions, node: str, rows: list[dict], attached: dict | None) -> dict:
    """The session's verified live row in one listing; SessionGap while an update's respawn hides it.

    For a background id verified live before (`attached`, a row with its id and last live PID) a row still
    registering its PID or in a state between two processes is a gap, as are a listing without the id while
    that process lives and (ProcessEnded) a row still listing a PID whose process ended or a listing without
    the id once it ended. A first attach, a terminal state and every identity refusal fail at once: nothing
    is attached without a verified live row. attach-one and the controller's waits (UpdateGaps) judge alike.
    """
    try:
        row = sessions.locate(node, rows)
    except RuntimeError as error:
        if attached is None:
            raise
        if str(error).startswith(PROCESS_ENDED):
            raise ProcessEnded(PROCESS_ENDED) from error
        terminal = any(listed.get("id") == attached["id"] and listed.get("state") in TERMINAL_STATES for listed in rows)
        if terminal or not str(error).startswith(TRANSIENT_REFUSALS):
            raise
        raise SessionGap(str(error)) from error
    if row is None:
        if attached is None:
            raise RuntimeError("Session unavailable; refusing implicit restart")
        if not process_alive(attached["pid"]):
            # Without --all `claude agents` omits a finished (`done`) session that has no process: an idle one between
            # the two processes of an update's respawn, or one that ended.
            raise ProcessEnded("Session unavailable; refusing implicit restart")
        raise SessionGap(f"`claude agents` does not list {attached['id']}")
    if not process_alive(row["pid"]):  # A zombie passes locate's kill(pid, 0).
        raise ProcessEnded(PROCESS_ENDED) if attached is not None else RuntimeError(PROCESS_ENDED)
    return row


class UpdateGaps:
    """The controller's waits and stops under attach-one's rules: an update's respawn gap is never a verdict on a session.

    A node whose receipt is bound (its background id verified live at launch) that the listing shows in a gap
    (verified_row) raises SessionGap, and the caller looks at it again (a wait at its next poll, a stop after
    2 seconds) for DEAD_PID_GRACE_SECONDS from when that gap was first seen; a gap that lasts longer is
    TransientInfraError, so the run stops nothing and resumes. A receipt not bound yet keeps locate's plain answer.
    """

    def __init__(self, sessions: InteractiveSessions, directory: Path, clock):
        self.sessions, self.directory, self.clock = sessions, directory, clock
        self.since: dict[str, float] = {}  # When each node's current gap was first seen.
        self.pids: dict[str, int] = {}     # Each node's last live PID.

    def row(self, node: str, rows: list[dict]) -> dict | None:
        """The node's verified live row, or locate's answer while its receipt is not bound; SessionGap while a gap lasts."""
        path = self.directory / f"{node}.interactive.json"
        bound = read_json(path).get("background_id") if path.exists() else None
        if not bound:
            return self.sessions.locate(node, rows)
        try:
            row = verified_row(self.sessions, node, rows, {"id": bound, "pid": self.pids.get(node)})
        except SessionGap as gap:
            now = self.clock()
            if now - self.since.setdefault(node, now) >= DEAD_PID_GRACE_SECONDS:
                raise TransientInfraError(f"Claude Code has not listed a live {node} session ({bound}) for {DEAD_PID_GRACE_SECONDS}s "
                                          f"({gap}); an update may still be respawning it") from gap
            raise
        self.since.pop(node, None)
        self.pids[node] = row["pid"]
        return row


def attach_one(sessions: InteractiveSessions, node: str, *, clock=time.monotonic, sleep=time.sleep) -> None:
    """Attach one session in this terminal, and attach it again after a lost connection.

    `claude attach` exits 0 when the operator detaches (Ctrl+Z, or ← to the agent view) or the session
    ended, and non-zero when it loses the background service. After each attach the run's own records
    decide: a stop the controller recorded ends attach-one with one line, a live session the controller
    has not stopped is attached again after a bounded backoff (also after exit 0 when the service respawned
    it under a new PID: a detach never changes the PID), and a session gone without a recorded stop is
    refused. `claude attach` would wake a missing session, so only an exact live row is ever attached.
    """
    failures, attached = 0, None  # attached: the row of the last attach
    ended = None  # How the last attach ended ("detached", "interrupted" or "lost"); None once decided, or before the first.
    dead_since = last_error = None  # When a row was first seen listing an ended process; what made the latest attempt fail.
    while True:
        if stop_reported(sessions.directory, node):
            return
        try:
            row = observe(sessions, node, attached)
        except ProcessEnded as gap:
            # A respawn lists its new PID within seconds; a session that keeps missing a live process has ended.
            now = clock()
            dead_since = now if dead_since is None else dead_since
            if now - dead_since >= DEAD_PID_GRACE_SECONDS:
                raise
            row, last_error = None, str(gap)
        except SessionGap as gap:
            row, last_error = None, str(gap)
        else:
            dead_since = None
        respawned = row is not None and ended is not None and row["pid"] != attached["pid"]
        if ended == "interrupted" or (ended == "detached" and row is not None and not respawned):
            return  # The operator detached or interrupted the attach; the session keeps running.
        if row is not None and ended is None:
            if stop_reported(sessions.directory, node):
                return  # The controller's stop intent precedes `claude stop`: a session it is stopping is never attached.
            attached, started = row, clock()
            try:
                code = subprocess.run([sessions.executable, "attach", row["id"]], cwd=sessions.node_worktree(node)).returncode
                failure = f"`claude attach` exited {code}"
            except OSError as error:
                code, failure = 1, str(error)  # An update is replacing the CLI itself: retried like a lost connection.
            if clock() - started >= ATTACH_STABLE_SECONDS:
                failures = 0  # It was connected for a while: its end starts a new count.
            # An attach the operator interrupted (Ctrl+C: 130, or killed by SIGINT) is never retried.
            ended = "interrupted" if code in (130, -signal.SIGINT) else "detached" if code == 0 else "lost"
            if ended == "lost":
                last_error = failure
            continue  # The records decide first: a stop, or a session that ended, is never waited for.
        failures += 1
        if failures >= REATTACH_LIMIT:
            raise RuntimeError(f"Gave up reattaching {node} ({attached['id']}) after {REATTACH_LIMIT} attempts in a row; the session may still "
                               f"be running. Rerun attach-one once `claude agents` lists it again"
                               + (f"; last error: {last_error}" if last_error else ""))
        delay = min(2 ** failures, REATTACH_MAX_DELAY)
        if respawned:
            print(f"The background service respawned {node} ({attached['id']}) as PID {row['pid']}; reattaching in {delay}s…",
                  file=sys.stderr, flush=True)
        elif ended == "lost":
            print(f"Lost the connection to {node} ({attached['id']}); the background service may be restarting. Reattaching in {delay}s…",
                  file=sys.stderr, flush=True)
        else:
            print(f"The background service does not list {node} ({attached['id']}) yet; retrying in {delay}s…", file=sys.stderr, flush=True)
        if row is not None or ended != "detached":
            ended = None  # A detach stays undecided until a row shows whether the PID changed.

    if item["status"] == "question":
        raise RuntimeError(f"Worker {node} asked a question that is not recorded yet: {item['question']}")
    return {"summary": item["summary"], "open_assumptions": item["open_assumptions"]}


def lanes(runtime) -> list[str]:
    """The run's selected lanes, from the runtime when it resolved them or from its plan."""
    return list(getattr(runtime, "workers", None) or plan_workers(runtime.plan))


def lane_deadline(runtime, node: str) -> float | None:
    """The lane's own deadline: its launch plus worker_timeout_seconds plus its answered questions' pauses; None while a question waits."""
    from .guardrails import deadline_extension
    extension = deadline_extension(runtime.directory, node)
    if extension is None:
        return None
    receipt = read_json(runtime.directory / f"{node}.interactive.json")
    return datetime.fromisoformat(receipt["launch_requested_at"]).timestamp() + runtime.plan["automatic"]["worker_timeout_seconds"] + extension


def latest_deadline(runtime, workers: list[str]) -> float | None:
    """The latest of the lanes' own deadlines; None while any lane's question waits (the run waits on its answer anyway)."""
    deadlines = [lane_deadline(runtime, node) for node in workers]
    return None if None in deadlines else max(deadlines)


def question_asked_at(runtime, node: str, now: float) -> float:
    """When the worker wrote its question: the completion file carries no time of its own, so its modification time.

    Never later than now, nor before the lane's deadline last ran again (its launch, or its previous question's answer),
    so a question first read late (the controller away across the deadline, a slow poll) pauses the deadline from when
    it was asked, and no paused time counts twice.
    """
    from .guardrails import epoch, load_questions
    receipt = read_json(runtime.directory / f"{node}.interactive.json")
    ran = [epoch(entry["answered_at"]) for entry in load_questions(runtime.directory, node) if entry["answered_at"]]
    ran.append(datetime.fromisoformat(receipt["launch_requested_at"]).timestamp())
    return max(min(now, (runtime.directory / f"{node}.completion.json").stat().st_mtime), *ran)


def wait_handoffs(runtime, *, clock=time.time, sleep=time.sleep) -> None:
    """Idle alone never means completion. Deadlines survive controller restart.

    A lane's deadline runs from its launch to its completion signal: a lane that finished is not held to it while
    others work; once every lane's signal was accepted, one whose session works again is held to the latest lane deadline.
    A 1.1.0 `question` completion pauses only that lane's deadline (persisted in `<node>.deadline.json`) from when it was
    written until the operator answers, with `workflow answer` or by typing in the pane; the other lanes keep running.
    """
    from .guardrails import (PANE_ANSWER, deadline_met, iso, load_questions, mark_deadline_met, record_pane_answer, record_question,
                             waiting_question)
    validate_automatic(runtime.plan)
    workers = lanes(runtime)
    if any((runtime.directory / f"{node}.stop.json").exists() for node in workers):
        # Recover a controller crash after durable handoffs/stop intent, before snapshot.
        for node in workers:
            if read_completion(runtime, node) != read_json(runtime.directory / f"{node}.handoff.json"):
                raise RuntimeError("Handoff changed after stop intent")
        return
    attention: set[str] = set()
    # Lanes whose completion signal was accepted once their turn ended: their deadline is met while another lane still
    # needs the run, whatever their session does afterwards (an operator prompt in its pane, a command of its own). Kept
    # across controller restarts.
    met = {node for node in workers if deadline_met(runtime.directory, node)}
    bounds: dict[str, float] = {}  # The latest lane deadline last announced for a met lane that is out again.
    # Answers recorded before this controller started need no second event.
    answered = {(node, entry["n"]) for node in workers for entry in load_questions(runtime.directory, node) if entry["answer"] is not None}
    gaps = UpdateGaps(runtime.sessions, runtime.directory, clock)
    while True:
        rows = runtime.sessions.inventory()
        handoffs = {}
        for node in workers:
            try:
                row = gaps.row(node, rows)
            except SessionGap:
                continue  # An update is respawning this lane's session (an idle one: finished, or paused on a question); no verdict.
            if row is None:
                raise RuntimeError("Native worker missing; reconciliation required")
            path = runtime.directory / f"{node}.completion.json"
            # The turn is over, so the file is final. A turn that ends on a question reports idle, done or, waiting on
            # the operator, blocked; a `completed` or `blocked` file is still accepted only once idle or done, as before.
            item = read_signal(runtime, node) if row["state"] in {"idle", "done", "blocked"} and path.exists() else None
            waiting = waiting_question(runtime.directory, node)
            if waiting and (row["state"] == "working" or item):
                # Working again while the question waits: its deadline runs again. A reply typed in the pane may never show
                # `working` (the registry can report the whole reply turn as blocked, or keep done), so the next completion
                # signal proves it too, before it is recorded or accepted. `answer` may have landed meanwhile (then nothing
                # is recorded); until that next signal it still records and delivers an answer.
                record_pane_answer(runtime.directory, node, clock)
                waiting = None
            for entry in load_questions(runtime.directory, node):
                if entry["answer"] is not None and (node, entry["n"]) not in answered:
                    answered.add((node, entry["n"]))
                    if entry["answer"] != PANE_ANSWER:
                        message = f"Worker {node} question {entry['n']} answered; its deadline runs again"
                    elif item:
                        message = (f"Worker {node} wrote its next completion signal while question {entry['n']} waited: it worked again (an "
                                   "answer typed in its pane, or a command of its own) though no poll saw it working. Its deadline runs "
                                   f"again, and `answer` is refused for question {entry['n']}")
                    else:
                        message = (f"Worker {node} is working again while question {entry['n']} waits (an answer typed in its pane, or a "
                                   "command of its own); its deadline runs again, and `answer` still records and delivers an answer "
                                   "until the worker writes its next completion signal")
                    runtime.event(node, "interactive", message)
            if item and item["status"] != "question" and row["state"] != "blocked":
                handoffs[node] = read_completion(runtime, node)
                continue  # Its completion signal met the deadline.
            deadline = lane_deadline(runtime, node)  # None while a question waits: that lane has no running deadline.
            if node in met:
                # Its signal met its deadline: it never ends the run while another lane works or waits on a question. Once
                # every lane's signal was accepted that protects no lane, so the latest lane deadline bounds its session
                # working or blocked again: it never makes the run wait longer than the lanes' own deadlines would have.
                deadline = latest_deadline(runtime, workers) if deadline is not None and met == set(workers) else None
            if item and item["status"] == "question":
                # Written before the deadline, it pauses it from then, though first read after it (the controller away).
                asked = question_asked_at(runtime, node, clock())
                if deadline is None or asked < deadline:
                    record_question(runtime, node, item, lambda: asked)
                    continue
            if node in met and deadline is not None and bounds.get(node) != deadline:
                bounds[node] = deadline
                runtime.event(node, "interactive", f"Worker {node} is {row['state']} again after its completion signal was accepted, and so was "
                                                   f"every other lane's: the run waits for its turn to end until {iso(deadline)}, the latest lane deadline")
            if deadline is not None and clock() >= deadline:
                raise RuntimeError(f"Worker {node} deadline exhausted; no automatic relaunch")
            if row["state"] == "blocked" and not waiting and node not in attention:
                # A native session reports `blocked` when its turn ended needing a human: a question,
                # a permission prompt or a refusal the harness could not continue past. That is not a
                # failure of the lane, and the other lanes keep working. The operator may answer in the
                # pane; the worker deadline bounds the wait (a met lane's, as above). No billing/provider
                # fallback. A recorded question already said what it waits for, and its deadline is paused.
                attention.add(node)
                runtime.event(node, "interactive", f"Worker {node} needs attention in its pane (native state blocked); " + (
                    "its completion signal met its deadline, so the run waits for it while another lane works or waits on a question, "
                    "then until the latest lane deadline" if node in met else "waiting until its deadline"))
            elif row["state"] != "blocked":
                attention.discard(node)
        if set(handoffs) == set(workers):
            for node, value in handoffs.items():
                save_json(runtime.directory / f"{node}.handoff.json", value)
            return
        for node in set(handoffs) - met:
            mark_deadline_met(runtime.directory, node, clock())
            met.add(node)
        sleep(2)


# Finding attributions that name no single lane; the run's lane ids complete the vocabulary.
FINDING_ATTRIBUTIONS = ("multiple", "none")


def finding_workers(runtime) -> list[str]:
    """The `worker` vocabulary of this run's findings: its lane ids, then multiple and none."""
    return [*lanes(runtime), *FINDING_ATTRIBUTIONS]


def worker_vocabulary(runtime) -> str:
